export default function Home() {
  const tableRoute = useMemo(() => parseTableRoute(window.location.search), []);
  const tableNumber = tableRoute.tableNumber;
  const tableId = tableRoute.tableId;
  const [category, setCategory] = useState<Category>("Todos");
  const [query, setQuery] = useState("");
  const [priceFilter, setPriceFilter] = useState("todos");
  const [maxPrice, setMaxPrice] = useState("");
  const [selected, setSelected] = useState<Product | null>(null);
  const [showFilters, setShowFilters] = useState(false);
  const [notice, setNotice] = useState(false);
  const [sortBy, setSortBy] = useState("recommended");
  const [showFavorites, setShowFavorites] = useState(false);
  const [favorites, setFavorites] = useState<string[]>(() => { try { return JSON.parse(localStorage.getItem("patio-zambeze-favorites") || "[]"); } catch { return []; } });
  const activeMenuQuery = trpc.menu.active.useQuery(undefined, { retry: false });
  const catalogProducts = useMemo<Product[]>(() => {
    if (!activeMenuQuery.data?.length) return products;
    return activeMenuQuery.data.map(({ product, category: itemCategory }) => ({
      name: product.name,
      category: (["Entradas", "Pratos", "Hambúrgueres", "Bebidas", "Sobremesas"].includes(itemCategory?.name ?? "") ? itemCategory?.name : "Pratos") as Exclude<Category, "Todos">,
      description: product.description ?? "",
      price: Number(product.price),
      image: product.imageUrl ?? undefined,
      available: product.status === "ACTIVE",
      preparation: product.preparation ?? undefined,
    }));
  }, [activeMenuQuery.data]);
  const [selection, setSelection] = useState<Selection>({});
  const [lang, setLang] = useState<Lang>("pt");
  const [darkMode, setDarkMode] = useState(() => localStorage.getItem("patio-zambeze-dark-mode") === "true");
  const [statusAlertsEnabled, setStatusAlertsEnabled] = useState(() => localStorage.getItem("patio-zambeze-status-alerts") !== "false");
  const [sessionToken, setSessionToken] = useState<string | null>(null);
  useEffect(() => {
    const storageKey = sessionStorageKey(tableId || tableNumber);
    const cookieKey = sessionCookieKey(tableId || tableNumber);
    const resolveToken = () => {
      const cookieMatch = document.cookie.split("; ").find((part) => part.startsWith(`${cookieKey}=`));
      const cookieToken = cookieMatch?.slice(cookieKey.length + 1);
      const existing = cookieToken || localStorage.getItem(storageKey);
      const token = existing || `${crypto.randomUUID()}${crypto.randomUUID()}`;
      localStorage.setItem(storageKey, token);
      document.cookie = `${cookieKey}=${token}; Path=/; Max-Age=31536000; SameSite=Lax`;
      setSessionToken(token);
    };
    if (navigator.locks) {
      void navigator.locks.request("patio-zambeze-session-init", resolveToken);
    } else {
      resolveToken();
    }
  }, [tableId, tableNumber]);
  const copy = lang === "pt" ? { menu: "Menu digital", open: "Aberto hoje · 08:00–22:00", search: "Pesquisar no menu...", choices: "Escolhas da casa", recommended: "Recomendados", share: "Feito para partilhar", house: "O menu da casa", filter: "Filtrar por preço", favorites: "Meus favoritos", order: "Ordenar por", clear: "Limpar filtros", start: "Para começar", items: "itens", details: "Ver detalhes", select: "+ Selecionar", selected: "Selecionado", waiter: "Para fazer o pedido, chame o garçom.", about: "Sobre o restaurante", address: "Endereço", phone: "Telefone", whatsapp: "WhatsApp", social: "Redes sociais", preparation: "Preparação", continue: "Continuar a consultar", selection: "Minha Seleção", draft: "Histórico da mesa", estimated: "TOTAL ESTIMADO", showWaiter: "Confirmar ao Garçom", emptySelection: "A sua seleção está vazia.", unit: "por unidade", subtotal: "Subtotal", remove: "Remover" } : { menu: "Digital menu", open: "Open today · 08:00–22:00", search: "Search the menu...", choices: "House choices", recommended: "Recommended", share: "Made to share", house: "The house menu", filter: "Filter by price", favorites: "My favourites", order: "Sort by", clear: "Clear filters", start: "To start", items: "items", details: "View details", select: "+ Select", selected: "Selected", waiter: "To order, please call the waiter.", about: "About the restaurant", address: "Address", phone: "Phone", whatsapp: "WhatsApp", social: "Social media", preparation: "Preparation", continue: "Continue browsing", selection: "My Selection", draft: "Table history", estimated: "ESTIMATED TOTAL", showWaiter: "Confirm to Waiter", emptySelection: "Your selection is empty.", unit: "per unit", subtotal: "Subtotal", remove: "Remove" };
  const [showSelection, setShowSelection] = useState(false);
  const [selectionNotice, setSelectionNotice] = useState(false);
  const [selectionNoticeText, setSelectionNoticeText] = useState("");
  const historyInput = useMemo(() => ({ sessionToken: sessionToken || "", tableNumber, tableId }), [sessionToken, tableNumber, tableId]);
  const notificationStorageKey = useMemo(() => `patio-zambeze-status-notifications-${tableId || tableNumber}`, [tableId, tableNumber]);
  const [statusNotifications, setStatusNotifications] = useState<StatusNotification[]>(() => { try { return JSON.parse(localStorage.getItem(`patio-zambeze-status-notifications-${tableId || tableNumber}`) || "[]"); } catch { return []; } });
  useEffect(() => { try { setStatusNotifications(JSON.parse(localStorage.getItem(notificationStorageKey) || "[]")); } catch { setStatusNotifications([]); } }, [notificationStorageKey]);
  const historyQuery = trpc.tableHistory.list.useQuery(historyInput, { enabled: Boolean(sessionToken), refetchInterval: sessionToken ? 5000 : false });
  const sessionInfoQuery = trpc.tableHistory.sessionInfo.useQuery(historyInput, { enabled: Boolean(sessionToken), refetchInterval: sessionToken ? 5000 : false });
  const historyMutation = trpc.tableHistory.addSelection.useMutation({ onSuccess: (result) => { if (result.sessionToken && result.sessionToken !== sessionToken) {       persistSessionToken(tableId || tableNumber, result.sessionToken); setSessionToken(result.sessionToken); } void historyQuery.refetch(); } });
  useEffect(() => {
    if (historyQuery.error?.message !== "SESSION_CLOSED" || !sessionToken) return;
    const nextToken = `${crypto.randomUUID()}${crypto.randomUUID()}`;
    persistSessionToken(tableId || tableNumber, nextToken);
    setSessionToken(nextToken);
  }, [historyQuery.error, sessionToken, tableNumber]);
  const invalidQrCode = Boolean(tableId && sessionInfoQuery.error?.message === "TABLE_NOT_FOUND");
  const identifiedTableNumber = sessionInfoQuery.data?.session.tableNumber || tableNumber;
  const history: HistoryEntry[] = (historyQuery.data || []).map((entry) => ({ id: entry.selectionNumber, createdAt: new Date(entry.createdAt).toISOString(), subtotal: entry.subtotal, viewedAt: entry.viewedAt ? new Date(entry.viewedAt).toISOString() : null, status: entry.status ?? "PENDING", items: entry.items.map((item) => ({ name: item.productName, quantity: item.quantity, price: item.unitPrice })) }));
  const receiptReady = history.length > 0 && !historyQuery.isLoading;
  const receiptReleased = receiptReady && history.every((entry) => Boolean(entry.viewedAt));
  const toggleStatusAlerts = () => setStatusAlertsEnabled((enabled) => { const next = !enabled; localStorage.setItem("patio-zambeze-status-alerts", String(next)); return next; });
  const previousStatusesRef = useRef<Record<string, string>>({});
  useEffect(() => {
    const nextStatuses = Object.fromEntries(history.map((entry) => [String(entry.id), entry.status]));
    const previousStatuses = previousStatusesRef.current;
    const changed = history.find((entry) => previousStatuses[String(entry.id)] && previousStatuses[String(entry.id)] !== entry.status && ["PENDING", "PREPARING", "READY", "DELIVERED"].includes(entry.status));
    if (changed) {
      const notification: StatusNotification = { id: `${changed.id}-${changed.status}-${Date.now()}`, selectionId: changed.id, status: changed.status, createdAt: new Date().toISOString() };
      setStatusNotifications((current) => { const next = [notification, ...current.filter((item) => item.selectionId !== changed.id || item.status !== changed.status)].slice(0, 8); localStorage.setItem(notificationStorageKey, JSON.stringify(next)); return next; });
      if (statusAlertsEnabled) try {
        if (typeof navigator.vibrate === "function") navigator.vibrate([90, 45, 90]);
        const AudioContextConstructor = window.AudioContext || (window as Window & { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
        if (AudioContextConstructor) {
          const audioContext = new AudioContextConstructor();
          const oscillator = audioContext.createOscillator();
          const gain = audioContext.createGain();
          oscillator.frequency.value = changed.status === "DELIVERED" ? 660 : changed.status === "READY" ? 590 : changed.status === "PREPARING" ? 520 : 440;
          oscillator.type = "sine";
          gain.gain.setValueAtTime(0.0001, audioContext.currentTime);
          gain.gain.exponentialRampToValueAtTime(0.08, audioContext.currentTime + 0.02);
          gain.gain.exponentialRampToValueAtTime(0.0001, audioContext.currentTime + 0.22);
          oscillator.connect(gain).connect(audioContext.destination);
          oscillator.start();
          oscillator.stop(audioContext.currentTime + 0.24);
          window.setTimeout(() => void audioContext.close(), 400);
        }
      } catch { /* O browser pode bloquear áudio até existir uma interacção do utilizador. */ }
      const statusText = { PENDING: lang === "pt" ? "Pendente" : "Pending", PREPARING: lang === "pt" ? "Em preparação" : "Preparing", READY: lang === "pt" ? "Pronto" : "Ready", DELIVERED: lang === "pt" ? "Entregue" : "Delivered" }[changed.status] ?? changed.status;
      setSelectionNoticeText(lang === "pt" ? `🔔 Seleção ${changed.id}: ${statusText}.` : `🔔 Selection ${changed.id}: ${statusText}.`);
      setSelectionNotice(true);
      window.setTimeout(() => setSelectionNotice(false), 3600);
    }
    previousStatusesRef.current = nextStatuses;
  }, [history, lang, notificationStorageKey, statusAlertsEnabled]);
  const [pendingConfirmation, setPendingConfirmation] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const [pdfState, setPdfState] = useState<ReceiptPdfState>("idle");
  const [printState, setPrintState] = useState<ReceiptPrintState>("idle");
  const selectionItems = catalogProducts.filter((product) => selection[product.name]);
  const selectionUnits = Object.values(selection).reduce((total, quantity) => total + quantity, 0);
  const selectionTotal = selectionItems.reduce((total, product) => total + product.price * selection[product.name], 0);
  const historyTotal = history.reduce((total, entry) => total + entry.subtotal, 0);
  const receiptFilename = `RECIBO-MESA-${identifiedTableNumber || "mesa"}.pdf`;

  const handleShareReceiptPdf = async () => { if (!receiptReleased || pdfState !== "idle") return; setPdfState("sharing"); try { await shareReceiptPdf(`#client-receipt-${tableNumber || "mesa"} .receipt-print`, receiptFilename); setPdfState("idle"); } catch { setPdfState("error"); } };
  const handleDownloadReceiptPdf = async () => { if (!receiptReleased || pdfState !== "idle") return; setPdfState("preparing"); try { await downloadReceiptPdf(`#client-receipt-${tableNumber || "mesa"} .receipt-print`, receiptFilename); setPdfState("idle"); } catch { setPdfState("error"); } };
  const handlePrintReceipt = () => { if (!receiptReleased || printState !== "idle") return; printRenderedReceipt(`#client-receipt-${tableNumber || "mesa"} .receipt-print`, setPrintState); };
  const floatingBars = getFloatingBarVisibility({ historyCount: history.length, pendingUnits: selectionUnits, showHistory, showSelection });
  const historyIssue = historyQuery.isError || historyMutation.isError;
  const historyIssueText = lang === "pt" ? "Não foi possível sincronizar o histórico. Tente novamente." : "The history could not be synchronized. Please try again.";
  const updateSelection = (next: Selection) => { setSelection(next); };
  const addToSelection = (product: Product) => updateSelection({ ...selection, [product.name]: (selection[product.name] || 0) + 1 });
  const changeSelectionQuantity = (name: string, quantity: number) => { const next = { ...selection }; if (quantity <= 0) delete next[name]; else next[name] = quantity; updateSelection(next); };

  const filteredProducts = useMemo(() => catalogProducts.filter((product) => {
    const text = `${product.name} ${product.category}`.toLowerCase();
    const matchesCategory = category === "Todos" || product.category === category;
    const matchesQuery = text.includes(query.toLowerCase());
    const matchesRange = priceFilter === "todos" || (priceFilter === "100" && product.price <= 100) || (priceFilter === "100-250" && product.price > 100 && product.price <= 250) || (priceFilter === "250-500" && product.price > 250 && product.price <= 500) || (priceFilter === "500" && product.price > 500);
    const matchesMax = maxPrice === "" || product.price <= Number(maxPrice);
    const matchesFavorites = !showFavorites || favorites.includes(product.name);
    return matchesCategory && matchesQuery && matchesRange && matchesMax && matchesFavorites;
  }).sort((a, b) => sortBy === "lowest" ? a.price - b.price : sortBy === "highest" ? b.price - a.price : sortBy === "popular" ? Number(b.popular) - Number(a.popular) : Number(b.recommended) - Number(a.recommended)), [catalogProducts, category, query, priceFilter, maxPrice, sortBy, showFavorites, favorites]);

  const hasFilters = category !== "Todos" || query !== "" || priceFilter !== "todos" || maxPrice !== "" || sortBy !== "recommended" || showFavorites;
  const recommendedProducts = catalogProducts.filter((product) => product.recommended).slice(0, 3);
  const toggleFavorite = (name: string) => setFavorites((current) => { const next = current.includes(name) ? current.filter((item) => item !== name) : [...current, name]; localStorage.setItem("patio-zambeze-favorites", JSON.stringify(next)); return next; });
  const clearFilters = () => { setCategory("Todos"); setQuery(""); setPriceFilter("todos"); setMaxPrice(""); setSortBy("recommended"); setShowFavorites(false); };

  const categoryLabel = (category: Category) => lang === "en" ? categoryEnglish[category] : category;
  const productName = (product: Product) => lang === "en" ? englishNames[product.name] || product.name : product.name;
  const productDescription = (product: Product) => lang === "en" ? englishDescriptions[product.name] || product.description : product.description;
  const productPreparation = (product: Product) => getMenuPreparation(product.name, lang) || product.preparation;
  const productImage = (product: Product) => productImages[product.name] || product.image;
  const showToWaiter = () => { setPendingConfirmation(true); };
  const confirmHistory = () => { if (!sessionToken || !selectionItems.length || historyMutation.isPending) return; historyMutation.mutate({ sessionToken, tableNumber, tableId, subtotal: selectionTotal, items: selectionItems.map((product) => ({ productName: product.name, preparation: product.preparation, quantity: selection[product.name], unitPrice: product.price })) }, { onSuccess: () => { updateSelection({}); setPendingConfirmation(false); setShowSelection(false); setSelectionNoticeText(lang === "pt" ? "✓ Seleção adicionada ao histórico da mesa." : "✓ Selection added to table history."); setSelectionNotice(true); window.setTimeout(() => setSelectionNotice(false), 3200); } }); };
  const receiptNow = new Date();
  const receiptDateTime = receiptNow.toLocaleString(lang === "pt" ? "pt-PT" : "en-GB", { dateStyle: "short", timeStyle: "short" });
  const historyText = () => [`PÁTIO ZAMBEZE`, `HISTÓRICO DA MESA`, receiptDateTime, ``, ...history.flatMap((entry) => [`Seleção ${entry.id} — ${formatHistoryTime(entry.createdAt, lang)}`, `Estado: ${entry.status}`, ...entry.items.flatMap((item) => [`${productName(catalogProducts.find((p) => p.name === item.name) || catalogProducts[0])}`, `${item.quantity} × ${money(item.price)} = ${money(item.quantity * item.price)}`]), `Subtotal: ${money(entry.subtotal)}`, `--------------------`]), `TOTAL ESTIMADO DA MESA: ${money(historyTotal)}`, ``, lang === "pt" ? "Este histórico é apenas um resumo temporário. Confirme os produtos e valores com o garçom." : "This history is only a temporary summary. Confirm products and prices with the waiter."].join("\n");
  const shareHistory = async () => { if (!receiptReleased) return; const text = historyText(); if (navigator.share) await navigator.share({ title: "Recibo da mesa", text }); else { await navigator.clipboard?.writeText(text); setSelectionNoticeText(lang === "pt" ? "✓ Recibo partilhado." : "✓ Receipt shared."); setSelectionNotice(true); window.setTimeout(() => setSelectionNotice(false), 2400); } };
  const copyHistory = async () => { await navigator.clipboard?.writeText(historyText()); setSelectionNoticeText(lang === "pt" ? "✓ Histórico copiado." : "✓ History copied."); setSelectionNotice(true); window.setTimeout(() => setSelectionNotice(false), 2400); };
  const shareWaiterCode = async () => { if (!sessionToken) return; const text = lang === "pt" ? `Código temporário da mesa: ${sessionToken}` : `Temporary table code: ${sessionToken}`; if (navigator.share) await navigator.share({ title: lang === "pt" ? "Código da mesa" : "Table code", text }); else { await navigator.clipboard?.writeText(text); setSelectionNoticeText(lang === "pt" ? "✓ Código copiado para o garçom." : "✓ Code copied for the waiter."); setSelectionNotice(true); window.setTimeout(() => setSelectionNotice(false), 2400); } };

  const toggleDarkMode = () => setDarkMode((current) => { const next = !current; localStorage.setItem("patio-zambeze-dark-mode", String(next)); return next; });
  const callWaiter = () => { setNotice(true); window.setTimeout(() => setNotice(false), 4200); };

  if (invalidQrCode) {
    return <div className={`menu-app-shell min-h-screen ${darkMode ? "theme-dark" : "theme-light"} bg-[#F7F2E9] px-5 py-6 text-[#183A32] sm:px-8`}><main className="mx-auto flex min-h-[70vh] max-w-xl items-center justify-center"><section className="w-full border border-[#183A32]/12 bg-white p-7 text-center shadow-sm sm:p-10"><p className="font-sans text-[10px] font-bold uppercase tracking-[0.28em] text-[#C85A3F]">Pátio Zambeze · Menu</p><h1 className="mt-3 font-display text-3xl">QR Code inválido</h1><p className="mt-4 font-sans text-sm leading-relaxed text-[#183A32]/65">QR Code inválido ou mesa não encontrada.</p><p className="mt-2 font-sans text-xs text-[#183A32]/50">Peça ao restaurante para fornecer um QR Code válido.</p></section></main></div>;
  }

  return <div className={`menu-app-shell min-h-screen ${darkMode ? "theme-dark" : "theme-light"} bg-[#F7F2E9] text-[#183A32]`}>
    <header className="border-b border-[#183A32]/10 bg-[#F7F2E9]/95 px-5 pb-6 pt-5 backdrop-blur-sm sm:px-8">
      <div className="mx-auto flex max-w-6xl items-start justify-between gap-6"><div className="flex items-center gap-3"><img src="/manus-storage/logo-symbol_8f597d73.png" alt="Símbolo Pátio Zambeze" className="h-14 w-14 rounded-full object-cover" /><div><div className="header-tools"><div className="language-switch" role="group" aria-label="Language"><Languages className="h-4 w-4" /><button onClick={() => setLang("pt")} className={lang === "pt" ? "language-active" : ""}>PT</button><span>|</span><button onClick={() => setLang("en")} className={lang === "en" ? "language-active" : ""}>EN</button></div><button className={`icon-tool ${statusAlertsEnabled ? "icon-tool-active" : ""}`} aria-label={statusAlertsEnabled ? "Desactivar alertas de estado" : "Activar alertas de estado"} title={statusAlertsEnabled ? "Alertas sonoros e vibração activos" : "Alertas sonoros e vibração desactivados"} aria-pressed={statusAlertsEnabled} onClick={toggleStatusAlerts}>{statusAlertsEnabled ? <Bell className="h-4 w-4" /> : <BellOff className="h-4 w-4" />}</button><button className="icon-tool" aria-label="Acessibilidade" title="Acessibilidade"><Accessibility className="h-4 w-4" /></button><button className="icon-tool" aria-label={darkMode ? "Ativar modo claro" : "Ativar modo escuro"} title={darkMode ? "Modo claro" : "Modo escuro"} onClick={toggleDarkMode}>{darkMode ? <Sun className="h-4 w-4" /> : <Moon className="h-4 w-4" />}</button></div><div className="flex items-center gap-2"><p className="font-sans text-[10px] font-bold uppercase tracking-[0.28em] text-[#C85A3F]">{copy.menu}</p>{tableId && sessionInfoQuery.data && <span className="table-identity-pill" aria-label={`Mesa ${identifiedTableNumber}`}><MapPin className="h-3 w-3" /> Mesa {identifiedTableNumber}</span>}</div><h1 className="font-display text-3xl leading-none tracking-[-0.03em] sm:text-4xl">Pátio Zambeze</h1></div></div><div className="hidden max-w-[220px] text-right sm:block"><p className="font-display text-lg leading-tight">Escolha o seu sabor.</p><p className="mt-1 font-sans text-xs leading-relaxed text-[#183A32]/60">{copy.open} · {lang === "pt" ? "Atendimento presencial" : "In-person service"}</p></div></div>
      {tableId && sessionInfoQuery.isLoading && <div className="mx-auto mt-3 max-w-6xl font-sans text-xs text-[#183A32]/55" role="status">A validar a mesa…</div>}<div className="mx-auto mt-7 max-w-6xl"><label className="sr-only" htmlFor="menu-search">Pesquisar produto</label><div className="search-shell flex items-center gap-3 bg-white px-4 py-3"><Search className="h-5 w-5 text-[#C85A3F]" aria-hidden="true" /><input id="menu-search" value={query} onChange={(event) => setQuery(event.target.value)} placeholder={copy.search} className="w-full bg-transparent font-sans text-sm outline-none placeholder:text-[#183A32]/45" />{query && <button aria-label="Limpar pesquisa" onClick={() => setQuery("")} className="text-[#183A32]/50 transition hover:text-[#C85A3F]"><X className="h-4 w-4" /></button>}</div></div>
    </header>

    <main className="mx-auto max-w-6xl px-5 pb-28 sm:px-8"><section className="recommended-strip mt-6"><div className="flex items-center justify-between"><div><p className="eyebrow">{copy.choices}</p><h2 className="mt-1 font-display text-2xl">{copy.recommended}</h2></div><Sparkles className="h-5 w-5 text-[#C85A3F]" /></div><div className="recommended-list mt-4">{recommendedProducts.map((product) => <button key={product.name} onClick={() => setSelected(product)} className="recommended-item"><span className="recommended-dot">✦</span><span><strong>{productName(product)}</strong><small>{money(product.price)}</small></span></button>)}</div></section><section className="pt-7 sm:flex sm:items-end sm:justify-between"><div><p className="eyebrow"><Sparkles className="mr-2 inline h-3.5 w-3.5" /> {copy.share}</p><h2 className="mt-2 font-display text-4xl leading-none tracking-[-0.035em] sm:text-5xl">{copy.house}</h2></div><p className="mt-3 max-w-xs font-sans text-sm leading-relaxed text-[#183A32]/60 sm:mt-0 sm:text-right">Pátio Zambeze, sabores preparados para serem descobertos sem pressa.</p></section>
      <nav className="category-scroll mt-8 flex gap-2 overflow-x-auto pb-2" aria-label="Categorias">{categories.map((item) => <button key={item} onClick={() => setCategory(item)} className={`category-pill ${category === item ? "category-pill-active" : ""}`}>{categoryLabel(item)}</button>)}</nav>
      <section className="mt-4 border-y border-[#183A32]/10 py-3"><button onClick={() => setShowFilters(!showFilters)} className="flex w-full items-center justify-between text-left font-sans text-sm font-semibold"><span className="flex items-center gap-2"><SlidersHorizontal className="h-4 w-4 text-[#C85A3F]" /> {copy.filter}</span><ChevronDown className={`h-4 w-4 transition-transform ${showFilters ? "rotate-180" : ""}`} /></button>{showFilters && <div className="filter-panel mt-4 grid gap-3 sm:grid-cols-2"><select value={priceFilter} onChange={(event) => setPriceFilter(event.target.value)} className="field-control"><option value="todos">Todos os preços</option><option value="100">Até 100 MT</option><option value="100-250">100–250 MT</option><option value="250-500">250–500 MT</option><option value="500">Acima de 500 MT</option></select><label className="field-control flex items-center gap-2"><input value={maxPrice} onChange={(event) => setMaxPrice(event.target.value.replace(/\D/g, ""))} inputMode="numeric" placeholder="Preço máximo" className="w-full bg-transparent outline-none" /><span className="text-xs text-[#183A32]/50">MT</span></label></div>}</section>
      <div className="menu-tools mt-5"><button onClick={() => setShowFavorites(!showFavorites)} className={`favorites-toggle ${showFavorites ? "favorites-toggle-active" : ""}`}><Heart className="h-4 w-4" fill={showFavorites ? "currentColor" : "none"} /> Meus favoritos <span>{favorites.length}</span></button><label className="sort-control">{copy.order}<select value={sortBy} onChange={(event) => setSortBy(event.target.value)}><option value="recommended">{copy.recommended}</option><option value="lowest">{lang === "pt" ? "Menor preço" : "Lowest price"}</option><option value="highest">{lang === "pt" ? "Maior preço" : "Highest price"}</option><option value="popular">{lang === "pt" ? "Mais populares" : "Most popular"}</option></select></label>{hasFilters && <button onClick={clearFilters} className="clear-filters"><X className="h-3.5 w-3.5" /> Limpar filtros</button>}</div><div className="editorial-rule mt-8"><div><p className="eyebrow">{category === "Todos" ? (lang === "pt" ? "Da cozinha para a mesa" : "From kitchen to table") : `${lang === "pt" ? "Seleção" : "Selection"} · ${categoryLabel(category)}`}</p><h3 className="mt-2 font-display text-2xl">{showFavorites ? copy.favorites : category === "Todos" ? copy.start : categoryLabel(category)}</h3></div><span className="font-sans text-xs font-semibold uppercase tracking-[0.16em] text-[#183A32]/45">{filteredProducts.length} {copy.items}</span></div>
      {filteredProducts.length > 0 ? <div className="mt-4 grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{filteredProducts.map((product, index) => <div key={product.name} role="button" tabIndex={0} onClick={() => setSelected(product)} onKeyDown={(event) => { if (event.key === "Enter" || event.key === " ") setSelected(product); }} className={`product-card text-left ${!product.available ? "product-card-unavailable" : ""}`} style={{ animationDelay: `${index * 40}ms` }}>
        {productImage(product) ? <img loading="lazy" src={productImage(product)} alt={productName(product)} className="product-image" /> : <div className="product-image product-image-placeholder"><span className="fallback-mark" aria-hidden="true">☼</span><span>{product.category === "Bebidas" ? "Bebida fresca" : product.category}</span></div>}
        <div className="p-4"><div className="flex items-start justify-between gap-4"><div><p className="font-display text-xl leading-tight">{productName(product)}</p><p className="mt-1.5 line-clamp-2 font-sans text-sm leading-relaxed text-[#183A32]/60">{productDescription(product)}</p></div><div className="flex items-center gap-2"><span className="price-tag shrink-0">{money(product.price)}</span><button type="button" aria-label={favorites.includes(product.name) ? `Remover ${product.name} dos favoritos` : `Adicionar ${product.name} aos favoritos`} onClick={(event) => { event.stopPropagation(); toggleFavorite(product.name); }} className={`favorite-button ${favorites.includes(product.name) ? "favorite-button-active" : ""}`}><Heart className="h-4 w-4" fill={favorites.includes(product.name) ? "currentColor" : "none"} /></button></div></div><div className="mt-3 flex flex-wrap items-center gap-2">{product.tag && <span className={`product-tag ${tagClass[product.tag]}`}>{product.tag}</span>}{product.vegetarian && <span className="product-tag tag-veg">Vegetariano</span>}{!product.available && <span className="product-tag tag-unavailable">Indisponível no momento</span>}</div><div className="mt-4 flex items-center justify-between gap-3"><p className="font-sans text-[10px] font-bold uppercase tracking-[0.18em] text-[#C85A3F]">Ver detalhes <ChevronDown className="ml-1 inline h-3 w-3 -rotate-90" /></p><button type="button" onClick={(event) => { event.stopPropagation(); addToSelection(product); setSelectionNotice(true); window.setTimeout(() => setSelectionNotice(false), 1800); }} className="select-product-button">{selection[product.name] ? `✓ ${copy.selected} · ${selection[product.name]}` : copy.select}</button></div></div>
      </div>)}</div> : <div className="empty-state mt-5"><p className="font-display text-2xl">Nenhum produto encontrado.</p><p className="mt-2 font-sans text-sm text-[#183A32]/60">Tente outra categoria, palavra ou faixa de preço.</p></div>}
      <section className="waiter-note mt-12 flex flex-col gap-4 p-5 sm:flex-row sm:items-center sm:justify-between sm:p-6"><div><p className="eyebrow">{lang === "pt" ? "Atendimento presencial" : "In-person service"}</p><p className="mt-2 font-display text-2xl leading-tight">{copy.waiter}</p></div><button onClick={callWaiter} className="waiter-button">{lang === "pt" ? "Lembrar-me" : "Remind me"}</button></section>
      <button onClick={() => window.scrollTo({ top: 0, behavior: "smooth" })} className="back-top"><ArrowUp className="h-4 w-4" /> {lang === "pt" ? "Voltar ao topo" : "Back to top"}</button><section className="restaurant-info mt-10 grid gap-5 border-t border-[#183A32]/12 pt-6 sm:grid-cols-2"><div><p className="eyebrow">{copy.about}</p><h3 className="mt-2 font-display text-2xl">Pátio Zambeze</h3><p className="mt-2 max-w-sm font-sans text-sm leading-relaxed text-[#183A32]/62">{lang === "pt" ? "Um espaço para descobrir sabores de Moçambique com calma." : "A place to discover Mozambican flavours at your own pace."}</p><div className="restaurant-links mt-4"><a href="tel:+258840000000">{copy.phone}: +258 84 000 0000</a><a href="https://wa.me/258840000000">{copy.whatsapp}: +258 84 000 0000</a></div></div><div className="font-sans text-sm leading-7 text-[#183A32]/62 sm:text-right"><p><strong>{copy.open}</strong></p><p>{copy.address}: Av. Marginal, Maputo</p><p>{copy.social}: @patiozambeze</p><p className="font-semibold text-[#C85A3F]">{lang === "pt" ? "Digitalizar o menu, não o atendimento." : "Digitise the menu, not the service."}</p></div></section>
    </main>

    {floatingBars.showHistoryBar && <button className={`history-bar ${floatingBars.historyAboveSelection ? "history-bar-with-selection" : ""} ${showHistory ? "history-bar-exit" : "history-bar-enter"}`} onClick={() => setShowHistory(true)} aria-hidden={showHistory} tabIndex={showHistory ? -1 : 0}><span>🧾 {lang === "pt" ? "Histórico da Mesa" : "Table history"}</span><strong>{money(historyTotal)}</strong></button>}{floatingBars.showSelectionBar && <button className="selection-bar" onClick={() => setShowSelection(true)}><span>🧾 {copy.selection} <b>({selectionUnits})</b></span><strong>{money(selectionTotal)}</strong></button>}{selectionNotice && <div className="selection-toast" role="status">{selectionNoticeText || "✓ Adicionado à seleção"}</div>}{historyQuery.isLoading && <div className="history-sync-note" role="status">{lang === "pt" ? "A carregar o Histórico da Mesa…" : "Loading table history…"}</div>}{historyIssue && <div className="history-sync-error" role="alert">{historyIssueText} <button onClick={() => { historyQuery.refetch(); historyMutation.reset(); }}>{lang === "pt" ? "Tentar novamente" : "Retry"}</button></div>}{showSelection && <div className="modal-backdrop" role="presentation" onClick={() => setShowSelection(false)}><article className="detail-modal selection-modal" role="dialog" aria-modal="true" aria-labelledby="selection-title" onClick={(event) => event.stopPropagation()}><button onClick={() => setShowSelection(false)} aria-label="Continuar a consultar o menu" className="modal-close"><ChevronLeft className="h-5 w-5" /> <span>{copy.continue}</span></button><div className="p-6 sm:p-8"><p className="eyebrow">{copy.selection}</p><h2 id="selection-title" className="mt-2 font-display text-4xl leading-none">{copy.selection}</h2>{selectionItems.length > 0 ? <div className="mt-7 space-y-4">{selectionItems.map((product) => <div key={product.name} className="selection-row"><div><p className="font-display text-xl">{productName(product)}</p><p className="mt-1 font-sans text-xs text-[#183A32]/55">{money(product.price)} {copy.unit}</p><p className="mt-2 font-sans text-sm font-semibold">{copy.subtotal}: {money(product.price * selection[product.name])}</p></div><div className="selection-actions"><div className="quantity-control"><button aria-label={`Diminuir quantidade de ${product.name}`} onClick={() => changeSelectionQuantity(product.name, selection[product.name] - 1)}>−</button><span>{selection[product.name]}</span><button aria-label={`Aumentar quantidade de ${product.name}`} onClick={() => changeSelectionQuantity(product.name, selection[product.name] + 1)}>+</button></div><button className="remove-selection" onClick={() => changeSelectionQuantity(product.name, 0)}>{copy.remove}</button></div></div>)}</div> : <div className="empty-state mt-6">{copy.emptySelection}</div>}<div className="selection-total"><span>{copy.estimated}</span><strong>{money(selectionTotal)}</strong></div><p className="selection-disclaimer">{lang === "pt" ? "Este resumo não representa um pedido. Confirme os produtos e valores com o garçom. Os preços apresentados podem sofrer alterações." : "This summary is not an order. Confirm products and prices with the waiter. Prices may change."}</p><div className="selection-footer-actions"><button onClick={() => { if (window.confirm(lang === "pt" ? "Tem certeza que deseja limpar a sua seleção?" : "Are you sure you want to clear your selection?")) updateSelection({}); }} className="clear-selection">🗑️ {lang === "pt" ? "Limpar seleção" : "Clear selection"}</button><button onClick={showToWaiter} className="show-waiter">👨‍🍳 {copy.showWaiter}</button></div></div></article></div>}{pendingConfirmation && <div className="modal-backdrop" role="presentation" onClick={() => setPendingConfirmation(false)}><article className="detail-modal selection-modal" role="dialog" aria-modal="true" onClick={(event) => event.stopPropagation()}><button onClick={() => setPendingConfirmation(false)} aria-label="Voltar" className="modal-close"><ChevronLeft className="h-5 w-5" /> <span>{lang === "pt" ? "Voltar" : "Back"}</span></button><div className="p-6 sm:p-8"><p className="eyebrow">{lang === "pt" ? "Confirmação" : "Confirmation"}</p><h2 className="mt-2 font-display text-4xl leading-none">{lang === "pt" ? "Confira a sua seleção" : "Review your selection"}</h2><p className="mt-4 font-sans text-sm leading-relaxed text-[#183A32]/65">{lang === "pt" ? "Confira a sua seleção antes de apresentá-la ao garçom. Depois de confirmar, esta seleção será adicionada ao histórico da mesa e não poderá ser alterada pelo menu." : "Review your selection before showing it to the waiter. After confirmation, this selection will be added to table history and cannot be changed in the menu."}</p><div className="mt-6 space-y-3">{selectionItems.map((product) => <div key={product.name} className="history-line"><span>{productName(product)} · {selection[product.name]} × {money(product.price)}</span><strong>{money(selection[product.name] * product.price)}</strong></div>)}</div><div className="selection-total"><span>{copy.estimated}</span><strong>{money(selectionTotal)}</strong></div><button onClick={confirmHistory} className="show-waiter mt-6 w-full">{historyMutation.isPending ? (lang === "pt" ? "A guardar…" : "Saving…") : `✓ ${lang === "pt" ? "Confirmar e Adicionar ao Histórico" : "Confirm and Add to History"}`}</button></div></article></div>}{showHistory && <div className="modal-backdrop" role="presentation" onClick={() => setShowHistory(false)}><article className="detail-modal selection-modal receipt-modal receipt-58mm" role="dialog" aria-modal="true" onClick={(event) => event.stopPropagation()}><button onClick={() => setShowHistory(false)} aria-label="Continuar a consultar" className="modal-close"><ChevronLeft className="h-5 w-5" /> <span>{copy.continue}</span></button><div className="p-6 sm:p-8"><p className="eyebrow">{lang === "pt" ? "Recibo da mesa" : "Table receipt"}</p><h2 className="mt-2 font-display text-4xl leading-none">{lang === "pt" ? "Recibo da mesa" : "Table receipt"}</h2>{history.length > 0 && <section className="status-notification-history" aria-labelledby="status-history-title"><div className="status-notification-history-heading"><div><p className="eyebrow">{lang === "pt" ? "Acompanhamento" : "Tracking"}</p><h3 id="status-history-title">{lang === "pt" ? "Actualizações do pedido" : "Order updates"}</h3></div></div><div className="status-notification-list">{history.map((entry) => <div className="status-notification-row" key={`status-${entry.id}`}><span>Seleção #{entry.id}</span><strong>{entry.status === "PENDING" ? (lang === "pt" ? "Pendente" : "Pending") : entry.status === "PREPARING" ? (lang === "pt" ? "Em preparação" : "Preparing") : entry.status === "READY" ? (lang === "pt" ? "Pronto" : "Ready") : entry.status === "DELIVERED" ? (lang === "pt" ? "Entregue" : "Delivered") : entry.status === "COMPLETED" ? (lang === "pt" ? "Concluído" : "Completed") : entry.status}</strong><time>{new Date(entry.createdAt).toLocaleTimeString(lang === "pt" ? "pt-PT" : "en-GB", { hour: "2-digit", minute: "2-digit" })}</time></div>)}</div></section>}
<div id={`client-receipt-${tableNumber || "mesa"}`} className="receipt-preview-paper"><ThermalReceipt selections={history.map((entry) => ({ id: entry.id, selectionNumber: entry.id, createdAt: entry.createdAt, subtotal: entry.subtotal, status: entry.status, items: entry.items.map((item, index) => ({ id: `${entry.id}-${index}`, productName: productName(catalogProducts.find((p) => p.name === item.name) || catalogProducts[0]), quantity: item.quantity, unitPrice: item.price, subtotal: item.quantity * item.price })) }))} total={historyTotal} width="58mm" language={lang} className="receipt-preview" tableLabel={sessionInfoQuery.data?.session.tableNumber || tableNumber} waiterName={sessionInfoQuery.data?.waiter?.name} waiterCode={sessionInfoQuery.data?.waiter?.waiterCode} waiterViewedAt={sessionInfoQuery.data?.session.viewedAt} /></div><div className="history-actions"><button disabled={!receiptReleased || printState !== "idle"} onClick={handlePrintReceipt}>🖨️ {printState === "preparing" ? (lang === "pt" ? "A preparar impressão…" : "Preparing print…") : printState === "printing" ? (lang === "pt" ? "A imprimir…" : "Printing…") : lang === "pt" ? "Imprimir recibo" : "Print receipt"}</button><button disabled={!receiptReleased || pdfState !== "idle"} onClick={handleDownloadReceiptPdf}>📄 {pdfState === "preparing" ? (lang === "pt" ? "A preparar PDF…" : "Preparing PDF…") : lang === "pt" ? "Baixar recibo em PDF" : "Download receipt PDF"}</button><button disabled={!receiptReleased || pdfState !== "idle"} onClick={handleShareReceiptPdf}>📤 {pdfState === "sharing" ? (lang === "pt" ? "A preparar partilha…" : "Preparing share…") : lang === "pt" ? "Partilhar recibo em PDF" : "Share receipt PDF"}</button>{pdfState === "error" && <span role="alert">{lang === "pt" ? "Não foi possível gerar o PDF." : "Could not generate the PDF."} <button onClick={() => setPdfState("idle")}>{lang === "pt" ? "Tentar novamente" : "Try again"}</button></span>}</div></div></article></div>}{selected && <div className="modal-backdrop" role="presentation" onClick={() => setSelected(null)}><article className="detail-modal" role="dialog" aria-modal="true" aria-labelledby="product-title" onClick={(event) => event.stopPropagation()}><button onClick={() => setSelected(null)} aria-label="Voltar ao menu" className="modal-close"><ChevronLeft className="h-5 w-5" /> <span>Voltar ao menu</span></button>{productImage(selected) && <img src={productImage(selected)} alt={productName(selected)} className="h-56 w-full object-cover sm:h-72" />}<div className="p-6 sm:p-8"><div className="flex flex-wrap items-center gap-2"><p className="eyebrow">{selected.category}</p>{selected.tag && <span className={`product-tag ${tagClass[selected.tag]}`}>{selected.tag}</span>}{!selected.available && <span className="product-tag tag-unavailable">Indisponível</span>}</div><h2 id="product-title" className="mt-3 font-display text-4xl leading-none">{productName(selected)}</h2><p className="mt-5 font-sans text-base leading-relaxed text-[#183A32]/70">{productDescription(selected)}</p><p className="mt-7 font-sans text-2xl font-bold text-[#C85A3F]">{money(selected.price)}</p><div className="detail-grid mt-7 border-t border-[#183A32]/10 pt-5">{selected.ingredients && <div><p className="detail-label">Ingredientes principais</p><p>{selected.ingredients}</p></div>}{selected.allergens && <div><p className="detail-label">Alergénios</p><p>{selected.allergens}</p></div>}{selected.spicy && <div><p className="detail-label">Picante</p><p>{selected.spicy === "Não picante" ? "🌶️ Não picante" : selected.spicy === "Médio" ? "🌶️🌶️ Médio" : "🌶️🌶️🌶️ Picante"}</p></div>}{selected.portion && <div><p className="detail-label">Porção</p><p>{selected.portion}</p></div>}{productPreparation(selected) && <div><p className="detail-label">{copy.preparation}</p><p>⏱️ {productPreparation(selected)}</p></div>}{selected.features && <div><p className="detail-label">Características</p><p>{selected.features}</p></div>}{selected.combines && <div><p className="detail-label">Combina bem com</p><p>{selected.combines}</p></div>}{selected.variations && <div><p className="detail-label">Opções informativas</p><p>{selected.variations}</p></div>}</div><div className="mt-7 flex gap-2 border-t border-[#183A32]/10 pt-5 font-sans text-sm leading-relaxed text-[#183A32]/65"><Info className="mt-0.5 h-4 w-4 shrink-0 text-[#C85A3F]" /> Para pedir este prato, chame o garçom da sua mesa.</div></div></article></div>}
    {notice && <div className="notice" role="status">Por favor, chame o garçom da sua mesa para fazer o pedido.</div>}
  </div>;
}
